INSERT INTO `feedback_questions` (`question_id`, `question_text`) VALUES
(1, 'Has the Teacher covered the entire syllabus as prescribed by University?'),
(2, 'Has the Teacher covered relevant topics beyond the syllabus?'),
(3, 'How would you rate the Teacher\'s effectiveness in terms of technical content/course content?'),
(4, 'How would you rate the Teacher\'s communication skills?'),
(5, 'How would you rate the Teacher\'s use of teaching aids?'),
(6, 'How would you rate the pace at which the contents were covered?'),
(7, 'How would you rate the Teacher\'s motivation and inspiration for students to learn?'),
(8, 'How would you rate the support provided for the development of students\' skills through practical demonstrations?'),
(9, 'How would you rate the support provided for the development of students\' skills through hands-on training?'),
(10, 'How clear were the Teacher\'s expectations of students?');
